function twoSum(nums, target) {
  const seen = new Map();                //@init
  for (let i = 0; i < nums.length; i++) { //@loop
    const need = target - nums[i];       //@need
    if (seen.has(need)) {                //@check
      return [seen.get(need), i];        //@ret
    }
    seen.set(nums[i], i);                //@set
  }
}

function isValid(s) {
  const stack = [];                                  //@init
  const pair = { ')':'(', ']':'[', '}':'{' };        //@pair
  for (const ch of s) {                              //@loop
    if (ch in pair) {                                //@isclose
      if (stack.pop() !== pair[ch]) return false;    //@pop
    } else {
      stack.push(ch);                                //@push
    }
  }
  return stack.length === 0;                         //@ret
}

function maxProfit(prices) {
  let minPrice = Infinity;                       //@init1
  let best = 0;                                  //@init2
  for (const p of prices) {                      //@loop
    if (p < minPrice) minPrice = p;              //@min
    else best = Math.max(best, p - minPrice);    //@best
  }
  return best;                                   //@ret
}

function numIslands(grid) {
  const R = grid.length, C = grid[0].length;      //@dims
  let count = 0;                                   //@init
  for (let r = 0; r < R; r++) {                    //@loopr
    for (let c = 0; c < C; c++) {                  //@loopc
      if (grid[r][c] === '1') {                    //@land
        count++;                                   //@count
        sink(r, c);                                //@sink
      }
    }
  }
  return count;                                    //@ret

  function sink(r, c) {                            //@fn
    if (r < 0 || c < 0 || r >= R || c >= C || grid[r][c] !== '1') return; //@base
    grid[r][c] = '0';                              //@mark
    sink(r + 1, c); sink(r - 1, c); sink(r, c + 1); sink(r, c - 1);       //@rec
  }
}

class LRUCache {
  constructor(cap) { this.cap = cap; this.map = new Map(); } //@ctor
  get(key) {
    if (!this.map.has(key)) return -1;       //@getmiss
    const val = this.map.get(key);           //@getval
    this.map.delete(key);                    //@getdel
    this.map.set(key, val);                  //@getset
    return val;
  }
  put(key, val) {
    if (this.map.has(key)) this.map.delete(key); //@putdel
    this.map.set(key, val);                  //@putset
    if (this.map.size > this.cap) {          //@over
      const oldest = this.map.keys().next().value; //@oldest
      this.map.delete(oldest);               //@evict
    }
  }
}

function lengthOfLongestSubstring(s) {
  const last = new Map();                          //@init
  let left = 0, best = 0;                          //@init2
  for (let right = 0; right < s.length; right++) { //@loop
    const ch = s[right];                           //@ch
    if (last.has(ch) && last.get(ch) >= left) {    //@dup
      left = last.get(ch) + 1;                     //@jump
    }
    last.set(ch, right);                           //@set
    best = Math.max(best, right - left + 1);       //@best
  }
  return best;                                     //@ret
}

function merge(intervals) {
  intervals.sort((a, b) => a[0] - b[0]);       //@sort
  const out = [intervals[0]];                  //@init
  for (let i = 1; i < intervals.length; i++) { //@loop
    const last = out[out.length - 1];          //@last
    const [start, end] = intervals[i];         //@cur
    if (start <= last[1]) {                    //@overlap
      last[1] = Math.max(last[1], end);        //@merge
    } else {
      out.push([start, end]);                  //@push
    }
  }
  return out;                                  //@ret
}

function trap(h) {
  let l = 0, r = h.length - 1;                  //@init
  let leftMax = 0, rightMax = 0, water = 0;     //@init2
  while (l < r) {                               //@while
    if (h[l] < h[r]) {                          //@cmp
      leftMax = Math.max(leftMax, h[l]);        //@ladd
      water += leftMax - h[l];                  //@ladd
      l++;                                      //@linc
    } else {
      rightMax = Math.max(rightMax, h[r]);      //@radd
      water += rightMax - h[r];                 //@radd
      r--;                                      //@rdec
    }
  }
  return water;                                 //@ret
}

function groupAnagrams(strs) {
  const groups = new Map();                    //@init
  for (const s of strs) {                      //@loop
    const key = s.split('').sort().join('');   //@key
    if (!groups.has(key)) groups.set(key, []); //@new
    groups.get(key).push(s);                   //@push
  }
  return [...groups.values()];                 //@ret
}

function exist(board, word) {
  const R = board.length, C = board[0].length;
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      if (dfs(r, c, 0)) return true;                  //@start
  return false;

  function dfs(r, c, i) {                             //@fn
    if (i === word.length) return true;               //@done
    if (r<0 || c<0 || r>=R || c>=C || board[r][c] !== word[i]) return false; //@bad
    const tmp = board[r][c];                          //@mark
    board[r][c] = '#';                                //@mark
    const found = dfs(r+1,c,i+1) || dfs(r-1,c,i+1) || //@next
                  dfs(r,c+1,i+1) || dfs(r,c-1,i+1);   //@next
    board[r][c] = tmp;                                //@undo
    return found;
  }
}

function longestPalindrome(s) {
  let start = 0, maxLen = 1;                          //@init
  const expand = (l, r) => {                          //@fn
    while (l >= 0 && r < s.length && s[l] === s[r]) { //@while
      l--; r++;                                       //@step
    }
    return r - l - 1;                                 //@len
  };
  for (let i = 0; i < s.length; i++) {                //@loop
    const len = Math.max(expand(i, i), expand(i, i + 1)); //@call
    if (len > maxLen) {                               //@better
      maxLen = len;                                   //@set
      start = i - Math.floor((len - 1) / 2);          //@set
    }
  }
  return s.slice(start, start + maxLen);              //@ret
}

function threeSum(nums) {
  nums.sort((a, b) => a - b);                       //@sort
  const res = [];
  for (let i = 0; i < nums.length - 2; i++) {       //@loop
    if (i > 0 && nums[i] === nums[i-1]) continue;   //@skip
    let l = i + 1, r = nums.length - 1;             //@lr
    while (l < r) {                                 //@while
      const sum = nums[i] + nums[l] + nums[r];      //@sum
      if (sum < 0) l++;                             //@small
      else if (sum > 0) r--;                        //@big
      else {
        res.push([nums[i], nums[l], nums[r]]);      //@hit
        while (l < r && nums[l] === nums[l+1]) l++; //@move
        while (l < r && nums[r] === nums[r-1]) r--; //@move
        l++; r--;                                   //@move
      }
    }
  }
  return res;                                       //@ret
}

class MedianFinder {
  constructor() {
    this.low = new MaxHeap();    // smaller half   //@ctor
    this.high = new MinHeap();   // bigger half    //@ctor
  }
  addNum(x) {
    this.low.push(x);                               //@pushlow
    this.high.push(this.low.pop());                 //@move
    if (this.high.size() > this.low.size())         //@back
      this.low.push(this.high.pop());               //@back
  }
  findMedian() {
    if (this.low.size() > this.high.size()) return this.low.peek(); //@odd
    return (this.low.peek() + this.high.peek()) / 2;                //@even
  }
}

function serialize(root) {
  const out = [];
  (function walk(node) {                    //@walk
    if (!node) { out.push('#'); return; }   //@null
    out.push(node.val);                     //@val
    walk(node.left);                        //@left
    walk(node.right);                       //@right
  })(root);
  return out.join(',');                     //@join
}

function deserialize(data) {
  const vals = data.split(',');             //@split
  let i = 0;                                //@split
  function build() {                        //@build
    const v = vals[i++];                    //@read
    if (v === '#') return null;             //@hash
    const node = new TreeNode(+v);          //@node
    node.left = build();                    //@bl
    node.right = build();                   //@br
    return node;
  }
  return build();
}

function racecar(target) {
  const queue = [[0, 1]];                         //@init
  const seen = new Set(['0,1']);                  //@init
  let steps = 0;                                  //@steps
  while (queue.length) {                          //@while
    for (let k = queue.length; k > 0; k--) {      //@level
      const [pos, speed] = queue.shift();         //@pop
      if (pos === target) return steps;           //@goal
      const a = [pos + speed, speed * 2];         //@A
      const r = [pos, speed > 0 ? -1 : 1];        //@R
      for (const [p, s] of [a, r]) {              //@try
        if (Math.abs(p) > 2 * target) continue;   //@prune
        const key = p + ',' + s;
        if (!seen.has(key)) { seen.add(key); queue.push([p, s]); } //@add
      }
    }
    steps++;                                      //@inc
  }
}

function largestVariance(s) {
  const freq = {};
  for (const ch of s) freq[ch] = (freq[ch] || 0) + 1;   //@freq
  let best = 0;                                         //@freq
  for (const major in freq) {                           //@pairs
    for (const minor in freq) {                         //@pairs
      if (major === minor) continue;
      let cMaj = 0, cMin = 0, minLeft = freq[minor];    //@init
      for (const ch of s) {                             //@scan
        if (ch === major) cMaj++;                       //@maj
        if (ch === minor) { cMin++; minLeft--; }        //@min
        if (cMin > 0) best = Math.max(best, cMaj - cMin); //@upd
        if (cMin > cMaj && minLeft > 0) { cMaj = 0; cMin = 0; } //@reset
      }
    }
  }
  return best;                                          //@ret
}

class Solution {
  constructor(w) {
    this.prefix = [];                          //@pre
    let sum = 0;                               //@pre
    for (const x of w) {                       //@loop
      sum += x;                                //@loop
      this.prefix.push(sum);                   //@push
    }
    this.total = sum;                          //@total
  }
  pickIndex() {
    const r = Math.floor(Math.random() * this.total) + 1; //@rand
    let lo = 0, hi = this.prefix.length - 1;   //@lohi
    while (lo < hi) {                          //@while
      const mid = (lo + hi) >> 1;              //@mid
      if (this.prefix[mid] < r) lo = mid + 1;  //@right
      else hi = mid;                           //@left
    }
    return lo;                                 //@ret
  }
}

function findKthLargest(nums, k) {
  const heap = new MinHeap();           //@init
  for (const x of nums) {               //@loop
    heap.push(x);                       //@push
    if (heap.size() > k) heap.pop();    //@trim
  }
  return heap.peek();                   //@ret
}

function ladderLength(begin, end, wordList) {
  const dict = new Set(wordList);                     //@dict
  if (!dict.has(end)) return 0;                       //@noend
  const queue = [[begin, 1]];                         //@init
  while (queue.length) {                              //@while
    const [word, steps] = queue.shift();              //@pop
    if (word === end) return steps;                   //@goal
    for (let i = 0; i < word.length; i++) {           //@pos
      for (let c = 97; c <= 122; c++) {               //@letter
        const next = word.slice(0, i) + String.fromCharCode(c) + word.slice(i + 1); //@next
        if (dict.has(next)) {                         //@has
          dict.delete(next);                          //@has
          queue.push([next, steps + 1]);              //@has
        }
      }
    }
  }
  return 0;
}

function getDirections(root, startValue, destValue) {
  const toStart = [], toDest = [];                  //@init
  function find(node, target, path) {               //@find
    if (!node) return false;
    if (node.val === target) return true;           //@found
    path.push('L');                                 //@goL
    if (find(node.left, target, path)) return true; //@goL
    path.pop();                                     //@popL
    path.push('R');                                 //@goR
    if (find(node.right, target, path)) return true; //@goR
    path.pop();
    return false;
  }
  find(root, startValue, toStart);                  //@f1
  find(root, destValue, toDest);                    //@f2
  let i = 0;                                        //@strip
  while (i < toStart.length && i < toDest.length && toStart[i] === toDest[i]) i++; //@strip
  const ups = 'U'.repeat(toStart.length - i);       //@ups
  return ups + toDest.slice(i).join('');            //@ret
}

function removeDuplicates(nums) {
  if (nums.length === 0) return 0;          //@guard
  let write = 1;                            //@init
  for (let read = 1; read < nums.length; read++) { //@loop
    if (nums[read] !== nums[write - 1]) {   //@cmp
      nums[write] = nums[read];             //@copy
      write++;                              //@inc
    }
  }
  return write;                             //@ret
}

function containsDuplicate(nums) {
  const seen = new Set();            //@init
  for (const x of nums) {            //@loop
    if (seen.has(x)) return true;    //@check
    seen.add(x);                     //@add
  }
  return false;                      //@ret
}

function countOccurrences(nums) {
  const count = new Map();                      //@init
  for (const x of nums) {                       //@loop
    count.set(x, (count.get(x) || 0) + 1);      //@inc
  }
  const dupes = [];                             //@dupes
  for (const [num, c] of count) {               //@filter
    if (c > 1) dupes.push([num, c]);            //@keep
  }
  return dupes;                                 //@ret
}

function isAnagram(s, t) {
  if (s.length !== t.length) return false;               //@len
  const count = {};                                      //@init
  for (const ch of s) count[ch] = (count[ch] || 0) + 1;  //@plus
  for (const ch of t) {                                  //@loopt
    if (!count[ch]) return false;                        //@miss
    count[ch]--;                                         //@minus
  }
  return true;                                           //@ret
}

function isPalindrome(s) {
  let l = 0, r = s.length - 1;                          //@init
  while (l < r) {                                       //@while
    while (l < r && !isAlnum(s[l])) l++;                //@skipl
    while (l < r && !isAlnum(s[r])) r--;                //@skipr
    if (s[l].toLowerCase() !== s[r].toLowerCase()) return false; //@cmp
    l++; r--;                                           //@move
  }
  return true;                                          //@ret
}
const isAlnum = c => /[a-z0-9]/i.test(c);

function productExceptSelf(nums) {
  const n = nums.length;
  const out = Array(n).fill(1);              //@init
  let left = 1;                              //@left
  for (let i = 0; i < n; i++) {              //@lloop
    out[i] = left;                           //@lset
    left *= nums[i];                         //@lmul
  }
  let right = 1;                             //@right
  for (let i = n - 1; i >= 0; i--) {         //@rloop
    out[i] *= right;                         //@rset
    right *= nums[i];                        //@rmul
  }
  return out;                                //@ret
}

function twoSumII(numbers, target) {
  let l = 0, r = numbers.length - 1;          //@init
  while (l < r) {                             //@while
    const sum = numbers[l] + numbers[r];      //@sum
    if (sum === target) return [l + 1, r + 1]; //@hit
    if (sum < target) l++;                    //@small
    else r--;                                 //@big
  }
}

function compress(s) {
  let out = '';                                 //@init
  let count = 1;                                //@init
  for (let i = 1; i <= s.length; i++) {         //@loop
    if (i < s.length && s[i] === s[i - 1]) {    //@same
      count++;                                  //@inc
    } else {
      out += s[i - 1] + count;                  //@flush
      count = 1;                                //@reset
    }
  }
  return out.length < s.length ? out : s;       //@ret
}

function maxSubArray(nums) {
  let cur = nums[0], best = nums[0];         //@init
  for (let i = 1; i < nums.length; i++) {    //@loop
    cur = Math.max(nums[i], cur + nums[i]);  //@cur
    best = Math.max(best, cur);              //@best
  }
