}

function majorityElement(nums) {
  let candidate = null, votes = 0;          //@init
  for (const x of nums) {                   //@loop
    if (votes === 0) candidate = x;         //@pick
    votes += (x === candidate) ? 1 : -1;    //@vote
  }
  return candidate;                         //@ret
}

