function findMin(nums) {
  let lo = 0, hi = nums.length - 1;              //@init
  while (lo < hi) {                              //@while
    const mid = (lo + hi) >> 1;                  //@mid
    if (nums[mid] > nums[hi]) lo = mid + 1;      //@right
    else hi = mid;                               //@left
  }
  return nums[lo];                               //@ret
}

function search(nums, target) {
  let lo = 0, hi = nums.length - 1;                          //@init
  while (lo <= hi) {                                         //@while
    const mid = (lo + hi) >> 1;                              //@mid
    if (nums[mid] === target) return mid;                    //@hit
    if (nums[lo] <= nums[mid]) {                             //@leftsorted
      if (nums[lo] <= target && target < nums[mid]) hi = mid - 1; //@inleft
      else lo = mid + 1;                                     //@goright
    } else {
      if (nums[mid] < target && target <= nums[hi]) lo = mid + 1; //@inright
      else hi = mid - 1;                                     //@goleft
    }
  }
  return -1;                                                 //@ret
}

function isAlienSorted(words, order) {
  const rank = {};                                          //@rank
  for (let i = 0; i < order.length; i++) rank[order[i]] = i; //@rank
  for (let w = 0; w + 1 < words.length; w++) {              //@pair
    const a = words[w], b = words[w + 1];                   //@pair
    for (let i = 0; i < a.length; i++) {                    //@char
      if (i === b.length) return false;                     //@prefix
      if (a[i] !== b[i]) {                                  //@diff
        if (rank[a[i]] > rank[b[i]]) return false;          //@cmp
        break;                                              //@ok
      }
    }
  }
  return true;                                              //@ret
}

function nextPermutation(nums) {
  let i = nums.length - 2;                          //@i
  while (i >= 0 && nums[i] >= nums[i + 1]) i--;     //@pivot
  if (i >= 0) {                                     //@has
    let j = nums.length - 1;                        //@j
    while (nums[j] <= nums[i]) j--;                 //@find
    [nums[i], nums[j]] = [nums[j], nums[i]];        //@swap
  }
  reverse(nums, i + 1, nums.length - 1);            //@rev
}

function lengthOfLIS(nums) {
  const dp = Array(nums.length).fill(1);                  //@init
  for (let i = 1; i < nums.length; i++) {                 //@loopi
    for (let j = 0; j < i; j++) {                         //@loopj
      if (nums[j] < nums[i]) dp[i] = Math.max(dp[i], dp[j] + 1); //@upd
    }
  }
  return Math.max(...dp);                                 //@ret
}

function longestCommonSubsequence(a, b) {
  const dp = Array.from({length: a.length + 1}, () => Array(b.length + 1).fill(0)); //@init
  for (let i = 1; i <= a.length; i++) {                  //@loopi
    for (let j = 1; j <= b.length; j++) {                //@loopj
      if (a[i-1] === b[j-1]) dp[i][j] = dp[i-1][j-1] + 1; //@match
      else dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]);  //@skip
    }
  }
  return dp[a.length][b.length];                         //@ret
}

function wordBreak(s, wordDict) {
  const words = new Set(wordDict);                    //@set
  const dp = Array(s.length + 1).fill(false);         //@init
  dp[0] = true;                                       //@base
  for (let i = 1; i <= s.length; i++) {               //@loopi
    for (let j = 0; j < i; j++) {                     //@loopj
      if (dp[j] && words.has(s.slice(j, i))) {        //@check
        dp[i] = true;                                 //@mark
        break;                                        //@mark
      }
    }
  }
  return dp[s.length];                                //@ret
}

function eraseOverlapIntervals(intervals) {
  intervals.sort((a, b) => a[1] - b[1]);        //@sort
  let end = intervals[0][1], removed = 0;       //@init
  for (let i = 1; i < intervals.length; i++) {  //@loop
    if (intervals[i][0] < end) {                //@cmp
      removed++;                                //@remove
    } else {
      end = intervals[i][1];                    //@keep
    }
  }
  return removed;                               //@ret
}

function removeInterval(intervals, toBeRemoved) {
  const [rs, re] = toBeRemoved;                    //@init
  const out = [];                                  //@init
  for (const [s, e] of intervals) {                //@loop
    if (e <= rs || s >= re) {                      //@disjoint
      out.push([s, e]);                            //@keepall
    } else {
      if (s < rs) out.push([s, rs]);               //@left
      if (e > re) out.push([re, e]);               //@right
    }
  }
  return out;                                      //@ret
}

function fizzBuzz(n) {
  const out = [];                               //@init
  for (let i = 1; i <= n; i++) {                //@loop
    if (i % 15 === 0) out.push('FizzBuzz');     //@fb
    else if (i % 3 === 0) out.push('Fizz');     //@f
    else if (i % 5 === 0) out.push('Buzz');     //@b
    else out.push(String(i));                   //@num
  }
  return out;                                   //@ret
}

function longestCommonPrefix(strs) {
  for (let i = 0; i < strs[0].length; i++) {          //@col
    const ch = strs[0][i];                            //@ch
    for (const s of strs) {                           //@each
      if (i === s.length || s[i] !== ch) {            //@bad
        return strs[0].slice(0, i);                   //@ret
      }
    }
  }
  return strs[0];                                     //@all
}

function countSubstrings(s) {
