  for (let c = 0; c < s.length; c++) {                //@loop
    count += expand(c, c);                            //@odd
    count += expand(c, c + 1);                        //@even
  }
  return count;                                       //@ret

  function expand(l, r) {                             //@fn
    let n = 0;                                        //@n
