  while (i < str.length) {                                 //@dwhile
    let j = i;                                             //@j
    while (str[j] !== '#') j++;                            //@scan
    const len = Number(str.slice(i, j));                   //@len
    res.push(str.slice(j + 1, j + 1 + len));               //@take
    i = j + 1 + len;                                       //@next
  }
  return res;                                              //@dret
}

function fullJustify(words, maxWidth) {
  const res = [];                                           //@init
  let i = 0;                                                //@init
  while (i < words.length) {                                //@while
    let j = i, len = 0;                                     //@pack
    while (j < words.length && len + words[j].length + (j - i) <= maxWidth) { //@pack
      len += words[j].length; j++;                          //@pack
    }
    const gaps = j - i - 1;                                 //@gaps
    let line = words[i];                                    //@build
    if (j === words.length || gaps === 0) {                 //@last
      for (let k = i + 1; k < j; k++) line += ' ' + words[k]; //@last
      line = line.padEnd(maxWidth);                         //@last
    } else {
      const spaces = maxWidth - len;                        //@spread
      const each = Math.floor(spaces / gaps), extra = spaces % gaps; //@spread
      for (let k = i + 1; k < j; k++) {                     //@spread
        line += ' '.repeat(each + (k - i <= extra ? 1 : 0)) + words[k]; //@spread
      }
    }
    res.push(line);                                         //@push
    i = j;                                                  //@next
  }
  return res;                                               //@ret
}
